        entry: final entry,
        source: final source,
        positionMs: final positionMs,
        autoplay: final autoplay,
        gainDb: final gainDb,
      ):
        sse_encode_i_32(0, serializer);
        sse_encode_String(entry, serializer);
        sse_encode_box_autoadd_source(source, serializer);
        sse_encode_u_64(positionMs, serializer);
        sse_encode_bool(autoplay, serializer);
        sse_encode_f_32(gainDb, serializer);
      case PlayerCommand_EnqueueNext(
        entry: final entry,
        source: final source,
        gainDb: final gainDb,
      ):
        sse_encode_i_32(1, serializer);
        sse_encode_String(entry, serializer);
        sse_encode_box_autoadd_source(source, serializer);
        sse_encode_f_32(gainDb, serializer);
      case PlayerCommand_ReplaceNext(
        entry: final entry,
        source: final source,
        gainDb: final gainDb,
      ):
        sse_encode_i_32(2, serializer);
        sse_encode_String(entry, serializer);
        sse_encode_box_autoadd_source(source, serializer);
        sse_encode_f_32(gainDb, serializer);
      case PlayerCommand_ClearNext():
        sse_encode_i_32(3, serializer);
      case PlayerCommand_Stop():
        sse_encode_i_32(4, serializer);
    }
  }

